package com.apple.spark.core;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

import static org.junit.jupiter.api.Assertions.*;

public class LogDaoVerifyDBNameTest {

  @Test
  void nullDbNameThrowsRuntimeException() {
    RuntimeException ex =
        assertThrows(RuntimeException.class, () -> LogDao.verifyDBName(null));
    assertEquals("DB name should not be null or empty", ex.getMessage());
  }

  @Test
  void emptyDbNameThrowsRuntimeException() {
    RuntimeException ex =
        assertThrows(RuntimeException.class, () -> LogDao.verifyDBName(""));
    assertEquals("DB name should not be null or empty", ex.getMessage());
  }

  @ParameterizedTest
  @ValueSource(strings = {
      "dbName",
      "DB123_$",
      "a",
      "Z",
      "0",
      "$_",
      "abcDEF123$_",
      "____",
      "$$$$",
      "A1b2C3"
  })
  void validDbNamesDoNotThrow(String validName) {
    assertDoesNotThrow(() -> LogDao.verifyDBName(validName));
  }

  @ParameterizedTest
  @ValueSource(strings = {
      "name-with-dash",
      "name with space",
      "name!",
      "name.with.dot",
      "name%",
      "name/",
      "name@",
      "name#",
      "name:colon",
      "name,comma"
  })
  void invalidDbNamesThrowRuntimeExceptionWithDetailedMessage(String invalidName) {
    RuntimeException ex =
        assertThrows(RuntimeException.class, () -> LogDao.verifyDBName(invalidName));
    assertEquals("DB name should include only [^0-9a-zA-Z$_]: " + invalidName, ex.getMessage());
  }
}

